export function getTranscriptByEpisodeNumber(episodeNumber: number): PodcastTranscript | undefined {
  return podcastTranscripts.find((t) => t.episodeNumber === episodeNumber);
}

export function getTranscriptBySlug(slug: string): PodcastTranscript | undefined {
  return podcastTranscripts.find((t) => t.slug === slug);
}
